mapper.insert:
INSERT INTO INGREDIENT (
	INGREDIENT_ID, INGREDIENT_NAME, INGREDIENT_TYPE, DEFAULT_UNIT, ACTIVE_YN, CREATED_AT, UPDATED_AT	
) VALUES (
	SEQ_INGREDIENT.NEXTVAL, #{ingredientName}, #{ingredientType}, #{defaultUnit}, NVL(#{activeYn, jdbcType=VARCHAR}, 'Y'), SYSTIMESTAMP, SYSTIMESTAMP
)

mapper.select:
SELECT INGREDIENT_ID AS ingredientId, INGREDIENT_NAME AS ingredientName,
		INGREDIENT_TYPE AS ingredientType, DEFAULT_UNIT AS defaultUnit, ACTIVE_YN AS activeYn
FROM INGREDIENT WHERE INGREDIENT_NAME = #{ingredientName}
